package org.efootballrevival.runtimeprobe;import java.nio.file.*;public class PresenceTest{public static void main(String[]args)throws Exception{Path root=Files.createTempDirectory("ui74-presence-");Files.createDirectories(root.resolve("embedded-gateway/work/tools"));ResourceInstaller.Plan plan=new ResourceInstaller.Plan();String p="assetpacks/pad_ff_00/311010101/311010101/assets/pc0102_mobile_and.utoc",active="assetpacks/pad_ff_00/311010107/311010101/assets/pc0102_mobile_and.utoc";plan.add(p,4);plan.add("Download/version.bin",123);if(ResourcePresence.check(root.toFile(),plan,311010107))throw new AssertionError("marker-only accepted");Path old=root.resolve(p);Files.createDirectories(old.getParent());Files.write(old,new byte[4]);if(ResourcePresence.check(root.toFile(),plan,311010107))throw new AssertionError("stale version accepted");Path a=root.resolve(active);Files.createDirectories(a.getParent());Files.write(a,new byte[3]);if(ResourcePresence.check(root.toFile(),plan,311010107))throw new AssertionError("wrong size accepted");Files.write(a,new byte[4]);if(!ResourcePresence.check(root.toFile(),plan,311010107))throw new AssertionError("mutable Download should be excluded");Files.delete(a);if(ResourcePresence.check(root.toFile(),plan,311010107))throw new AssertionError("deleted asset accepted");System.out.println("{\"passed\":true,\"missing_and_wrong_size_rejected\":true,\"active_app_version_required\":true,\"mutable_Download_excluded\":true,\"deleted_after_previous_success_rejected\":true,\"device_tested\":false}");}}
